                    b.HasData(
                        new
                        {
                            Id = 1,
                            ContentBg = "<h2>Ценим вашата поверителност</h2>\n<p>Използваме бисквитки, за да осигурим правилното функциониране на сайта, да анализираме потреблението му и да подобрим вашето изживяване. Можете да изберете своите предпочитания и да ги промените по всяко време. За повече информация, моля, разгледайте нашата <a href=\"/Cookies\">Политика за бисквитки</a>.</p>",
                            ContentEn = "<h2>We value your privacy</h2>\n<p>We use cookies to ensure the site functions properly, analyze usage, and enhance your overall experience. You can choose your preferences and update them at any time. For more details, please review our <a href=\"/Cookies\">Cookie Policy</a>.</p>",
